import Foundation


struct RunnerListenerToken {
  static let requestHeaderName = "x-agent-device-runner-token"
  static let minimumByteCount = 32

  private let expected: [UInt8]

  init?(_ token: String?) {
    guard let token, token.utf8.count >= Self.minimumByteCount else { return nil }
    expected = Array(token.utf8)
  }


  func matches(_ presented: String) -> Bool {
    let candidate = Array(presented.utf8)
    var difference = candidate.count ^ expected.count
    for index in 0..<expected.count {
      let byte = index < candidate.count ? candidate[index] : 0
      difference |= Int(byte ^ expected[index])
    }
    return difference == 0
  }
}
